def has_hole(s):
    h,w=s['h'],s['w']; p=s['patt']
    # 0-cells inside bbox; hole if some 0-cell not reachable from bbox edge via 0-cells (4-conn)
    zero={(i,j) for i in range(h) for j in range(w) if p[i][j]==0}
    edge=[(i,j) for i in range(h) for j in range(w) if p[i][j]==0 and (i in(0,h-1) or j in(0,w-1))]
    seen=set(edge); st=list(edge)
    while st:
        a,b=st.pop()
        for da,db in((1,0),(-1,0),(0,1),(0,-1)):
            x,y=a+da,b+db
            if (x,y) in zero and (x,y) not in seen:
                seen.add((x,y)); st.append((x,y))
    return len(zero-seen)>0

